const pct = (vals, p) => { const s = [...vals].sort((a, b) => a - b); return s.length ? s[Math.max(0, Math.ceil(p * s.length) - 1)] : 0; };
const rate = (a, b) => (b ? Math.round((a / b) * 10000) / 10000 : 0);
const rows = $json.logs ?? [];
const errors = rows.filter((r) => r.status === 'error').length;
const by_route = {};
for (const r of rows) { const k = r.route ?? '오류'; by_route[k] = (by_route[k] ?? 0) + 1; }
const d = rows.map((r) => r.duration_ms);
const out = { total: rows.length, errors, error_rate: rate(errors, rows.length), p50_ms: pct(d, 0.5), p95_ms: pct(d, 0.95), by_route };
const group = (key) => { const g = {}; for (const r of rows) (g[key(r)] ??= []).push(r); return g; };
out.by_day = Object.fromEntries(Object.entries(group((r) => r.started_at.slice(0, 10))).sort().map(([k, v]) => {
  const e = v.filter((r) => r.status === 'error').length; return [k, { total: v.length, errors: e, error_rate: rate(e, v.length) }]; }));
out.by_release = {};
for (const r of rows.filter((x) => x.route === '자동 답변')) { const b = (out.by_release[r.release] ??= { answers: 0, repeats: 0 }); b.answers += 1; if (r.repeat) b.repeats += 1; }
for (const b of Object.values(out.by_release)) b.repeat_rate = rate(b.repeats, b.answers);
out.steps = {};
for (const k of ['faq_ms', 'answer_ms']) { const v = rows.map((r) => r.steps?.[k] ?? 0).filter((x) => x > 0); out.steps[k] = { runs: v.length, p50: pct(v, 0.5), p95: pct(v, 0.95) }; }
out.cost_usd = Math.round(rows.reduce((a, r) => a + (r.cost_usd ?? 0), 0) * 100000) / 100000;
out.cost_per_run = rows.length ? Math.round((out.cost_usd / rows.length) * 1000000) / 1000000 : 0;
out.llm_calls = rows.reduce((a, r) => a + (r.llm_calls ?? 0), 0);
return [{ json: out }];
